import { PDFDocument, StandardFonts, type PDFFont, type PDFImage, type PDFPage, rgb } from 'pdf-lib'

const PAGE_W = 595.32
const PAGE_H = 841.92
const M = 57
const BLACK = rgb(0, 0, 0)
const HEADER_PNG_B64 = ''

type PdfCtx = { page: PDFPage, y: number }

function b64ToBytes (b64: string): Uint8Array {
  const bin = atob(b64)
  const out = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
  return out
}

function cleanText (value: any): string {
  return String(value ?? '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/\uFB01/g, 'fi')
    .replace(/\uFB02/g, 'fl')
    .replace(/[\u00AD\u200B\u200C\u200D\uFEFF\u00A0]/g, ' ')
    .replace(/[\u2018\u2019]/g, '’')
    .replace(/[\u201C\u201D]/g, '”')
    .replace(/ +/g, ' ')
    .trim()
}

function safePdfText (value: any): string {
  return cleanText(value)
    .replace(/–/g, '-')
    .replace(/—/g, '-')
}

function v (m: Record<string, string>, key: string): string {
  return safePdfText(m[key] || '')
}

function valueOrBlank (value: string, blank = '_____'): string {
  const clean = safePdfText(value)
  return clean || blank
}

function ensureSemicolon (text: string): string {
  const clean = safePdfText(text)
  if (!clean) return ''
  return /[.;:]$/.test(clean) ? clean : `${clean};`
}

function ensurePeriod (text: string): string {
  const clean = safePdfText(text)
  if (!clean) return ''
  return /[.;:]$/.test(clean) ? clean : `${clean}.`
}

function stripTrailingPunctuation (text: string): string {
  return safePdfText(text).replace(/[.;:]$/, '')
}

function yearWords (year: string): string {
  const y = Number(year)
  if (y === 2026) return 'duemilaventisei'
  if (y === 2027) return 'duemilaventisette'
  if (y === 2028) return 'duemilaventotto'
  if (y === 2029) return 'duemilaventinove'
  if (y === 2030) return 'duemilatrenta'
  return year || 'duemilaventisei'
}

function textWidth (font: PDFFont, text: string, size: number): number {
  return font.widthOfTextAtSize(safePdfText(text), size)
}

function drawText (page: PDFPage, text: string, font: PDFFont, size: number, x: number, y: number): void {
  const s = safePdfText(text)
  if (!s) return
  page.drawText(s, { x, y, size, font, color: BLACK })
}

function drawCentered (page: PDFPage, text: string, font: PDFFont, size: number, y: number, underline = false): void {
  const s = safePdfText(text)
  const width = textWidth(font, s, size)
  const x = (PAGE_W - width) / 2
  drawText(page, s, font, size, x, y)
  if (underline) {
    page.drawLine({ start: { x, y: y - 2 }, end: { x: x + width, y: y - 2 }, thickness: 0.7, color: BLACK })
  }
}

function wrapWords (font: PDFFont, text: string, size: number, maxWidth: number): string[] {
  const source = safePdfText(text).replace(/\r/g, '')
  if (!source.trim()) return []
  const rows: string[] = []
  for (const para of source.split(/\n+/)) {
    const words = safePdfText(para).split(/\s+/).filter(Boolean)
    if (!words.length) continue
    let cur = words[0]
    for (let i = 1; i < words.length; i++) {
      const next = `${cur} ${words[i]}`
      if (textWidth(font, next, size) <= maxWidth) cur = next
      else {
        rows.push(cur)
        cur = words[i]
      }
    }
    rows.push(cur)
  }
  return rows
}

function addPage (doc: PDFDocument): PdfCtx {
  return { page: doc.addPage([PAGE_W, PAGE_H]), y: PAGE_H - 56 }
}

function needPage (ctx: PdfCtx, doc: PDFDocument, minHeight: number): void {
  if (ctx.y - minHeight >= 54) return
  const next = addPage(doc)
  ctx.page = next.page
  ctx.y = next.y
}

function drawHeader (page: PDFPage, headerImg: PDFImage | null): void {
  if (!headerImg) return
  page.drawImage(headerImg, { x: 84, y: PAGE_H - 86, width: 430, height: 53.2 })
}

function drawParagraph (ctx: PdfCtx, doc: PDFDocument, font: PDFFont, text: string, opts: { size?: number, lineH?: number, gap?: number, align?: 'left' | 'center' } = {}): void {
  const content = safePdfText(text)
  if (!content) return
  const size = opts.size ?? 12
  const lineH = opts.lineH ?? 15.5
  const gap = opts.gap ?? 7
  const width = PAGE_W - 2 * M
  const lines = wrapWords(font, content, size, width)
  needPage(ctx, doc, lines.length * lineH + gap)
  for (const line of lines) {
    needPage(ctx, doc, lineH + gap)
    if (opts.align === 'center') drawCentered(ctx.page, line, font, size, ctx.y)
    else drawText(ctx.page, line, font, size, M, ctx.y)
    ctx.y -= lineH
  }
  ctx.y -= gap
}

function drawMixedParagraph (ctx: PdfCtx, doc: PDFDocument, fR: PDFFont, fB: PDFFont, label: string, text: string, opts: { size?: number, lineH?: number, gap?: number } = {}): void {
  const rest = safePdfText(text)
  if (!rest && !label) return
  const size = opts.size ?? 12
  const lineH = opts.lineH ?? 15.5
  const gap = opts.gap ?? 7
  const width = PAGE_W - 2 * M
  const labelText = safePdfText(label)
  const labelWidth = labelText ? textWidth(fB, `${labelText} `, size) : 0
  const firstWords = rest.split(/\s+/).filter(Boolean)
  const lines: Array<{ label?: string, text: string }> = []
  let cur = ''
  let first = true
  for (const word of firstWords) {
    const next = cur ? `${cur} ${word}` : word
    const max = first ? width - labelWidth : width
    if (textWidth(fR, next, size) <= max) cur = next
    else {
      lines.push({ label: first ? labelText : undefined, text: cur })
      cur = word
      first = false
    }
  }
  lines.push({ label: first ? labelText : undefined, text: cur })
  needPage(ctx, doc, lines.length * lineH + gap)
  for (const line of lines) {
    needPage(ctx, doc, lineH + gap)
    if (line.label) {
      drawText(ctx.page, line.label, fB, size, M, ctx.y)
      drawText(ctx.page, line.text, fR, size, M + labelWidth, ctx.y)
    } else {
      drawText(ctx.page, line.text, fR, size, M, ctx.y)
    }
    ctx.y -= lineH
  }
  ctx.y -= gap
}

function drawSectionLabel (ctx: PdfCtx, doc: PDFDocument, fB: PDFFont, text: string, gapBefore = 8): void {
  needPage(ctx, doc, 28 + gapBefore)
  ctx.y -= gapBefore
  drawCentered(ctx.page, text, fB, 12, ctx.y)
  ctx.y -= 22
}

function drawTitleAndObject (ctx: PdfCtx, doc: PDFDocument, fR: PDFFont, fB: PDFFont, m: Record<string, string>): void {
  const anno = valueOrBlank(v(m, 'anno_corrente'), String(new Date().getFullYear()))
  const titolo = `DETERMINAZIONE DIRIGENZIALE N° ________/${anno} - D. AA. GG. - P. F.`
  drawCentered(ctx.page, titolo, fB, 12.5, ctx.y, true)
  ctx.y -= 40

  const trasgressore = v(m, 'trasgressore')
  const rawOggetto = v(m, 'bozza_determinazione_oggetto') || v(m, 'oggetto_atto_amm') || 'Contestazione di infrazione alle “Norme generali sulla distribuzione dell’acqua ad uso irriguo”.'
  const oggetto = safePdfText(rawOggetto)
    .replace(/\[NOME DITTA\s*\/\s*TRASGRESSORE\]/gi, trasgressore || '__________')
    .replace(/“\s*__________\s*”/g, trasgressore ? `“${trasgressore}”` : '“__________”')
    .toUpperCase()
  const label = 'OGGETTO:'
  const size = 12
  const lineH = 15.5
  const labelWidth = textWidth(fB, `${label} `, size)
  const maxFirst = PAGE_W - 2 * M - labelWidth
  const words = oggetto.split(/\s+/).filter(Boolean)
  const lines: string[] = []
  let cur = ''
  let first = true
  for (const word of words) {
    const next = cur ? `${cur} ${word}` : word
    const max = first ? maxFirst : PAGE_W - 2 * M - 120
    if (textWidth(fR, next, size) <= max) cur = next
    else {
      lines.push(cur)
      cur = word
      first = false
    }
  }
  if (cur) lines.push(cur)
  needPage(ctx, doc, lines.length * lineH + 24)
  lines.forEach((line, index) => {
    if (index === 0) {
      drawText(ctx.page, label, fB, size, M, ctx.y)
      drawText(ctx.page, line, fR, size, M + labelWidth, ctx.y)
    } else {
      const w = textWidth(fR, line, size)
      drawText(ctx.page, line, fR, size, (PAGE_W - w) / 2 + 26, ctx.y)
    }
    ctx.y -= lineH
  })
  ctx.y -= 24
}

function splitLabeledStatement (text: string): { label: string, rest: string } {
  const clean = safePdfText(text)
  const m = clean.match(/^(VISTA|VISTO|VISTE|DATO ATTO|RITENUTO|TUTTO CIÒ|CONSIDERATO|PRESO ATTO)\s+(.*)$/i)
  if (!m) return { label: '', rest: clean }
  return { label: m[1].toUpperCase(), rest: m[2] }
}

function drawStatement (ctx: PdfCtx, doc: PDFDocument, fR: PDFFont, fB: PDFFont, text: string): void {
  const parts = splitLabeledStatement(text)
  if (parts.label) drawMixedParagraph(ctx, doc, fR, fB, parts.label, parts.rest)
  else drawParagraph(ctx, doc, fR, text)
}

function drawDeterminaPoint (ctx: PdfCtx, doc: PDFDocument, fR: PDFFont, fB: PDFFont, label: string, text: string): void {
  drawMixedParagraph(ctx, doc, fR, fB, label, ensurePeriod(text), { gap: 7 })
}

function userParagraphs (text: string, prefix: string): string[] {
  const raw = String(text || '').replace(/\r/g, '').split(/\n+/).map(safePdfText).filter(Boolean)
  return raw.map(item => {
    if (/^(VIST[AOEI]|DATO ATTO|CONSIDERATO|RITENUTO|PRESO ATTO|di\s+)/i.test(item)) return ensureSemicolon(item)
    return ensureSemicolon(`${prefix}${item}`)
  })
}

function reportText (m: Record<string, string>): string {
  const rapporto = valueOrBlank(v(m, 'n_rapporto'))
  const dataRapporto = valueOrBlank(v(m, 'data_rapporto_tecnico'))
  const area = valueOrBlank(v(m, 'area'), '__________')
  const settore = valueOrBlank(v(m, 'settore'), '__________')
  const artRef = valueOrBlank(v(m, 'articoli_violati_riferimento'), 'dell’art. ____')
  return `VISTO il Rapporto tecnico di rilevazione n. ${rapporto} del ${dataRapporto}, redatto dall’Area ${area} / Settore ${settore}, con il quale sono stati rilevati i fatti riconducibili alla violazione ${artRef} delle suddette Norme generali;`
}

function propostaText (m: Record<string, string>): string {
  const protocollo = valueOrBlank(v(m, 'protocollo_fascicolo_numero'))
  const dataProtocollo = valueOrBlank(v(m, 'protocollo_fascicolo_data'))
  return `VISTA la Proposta di contestazione prot. n. ${protocollo} del ${dataProtocollo}, predisposta dal Settore Catasto, Ruoli e Servizi Territoriali, finalizzata alla contestazione dell’infrazione rilevata e alla quantificazione degli importi dovuti;`
}

function amountText (m: Record<string, string>): string {
  return valueOrBlank(v(m, 'pagamento_importo_totale'))
}

export async function buildBozzaDeterminazionePdf (m: Record<string, string>): Promise<Uint8Array> {
  const doc = await PDFDocument.create()
  const fR = await doc.embedFont(StandardFonts.TimesRoman)
  const fB = await doc.embedFont(StandardFonts.TimesRomanBold)
  let headerImg: PDFImage | null = null
  try { headerImg = await doc.embedPng(b64ToBytes(HEADER_PNG_B64)) } catch { headerImg = null }

  const ctx = addPage(doc)
  drawHeader(ctx.page, headerImg)
  ctx.y = PAGE_H - 142

  drawTitleAndObject(ctx, doc, fR, fB, m)

  const anno = valueOrBlank(v(m, 'anno_corrente'), String(new Date().getFullYear()))
  drawParagraph(ctx, doc, fR, `L’anno ${yearWords(anno)} il giorno ______ del mese di ________ in Cagliari, nella sede del Consorzio di Bonifica della Sardegna Meridionale - Via Dante n° 254`, { gap: 14 })

  drawCentered(ctx.page, 'IL DIRETTORE DELL’AREA AFFARI GENERALI', fB, 12, ctx.y)
  ctx.y -= 15
  drawCentered(ctx.page, 'E PROGRAMMAZIONE FINANZIARIA', fB, 12, ctx.y)
  ctx.y -= 28

  const premesse = [
    'VISTA la legge regionale n. 6 del 23 maggio 2008 recante “Legge - quadro in materia di consorzi di bonifica”;',
    'VISTO il vigente Statuto Consortile;',
    'VISTA la Deliberazione del Consiglio di Amministrazione n. 31 del 12 aprile 2024 con la quale è stato confermato l’incarico di Direttore dell’Area Affari Generali e Programmazione finanziaria alla dott.ssa Patrizia Mattioni;',
    'VISTO il Bilancio di Previsione per l’esercizio 2026 approvato con Deliberazione del Consiglio dei Delegati n. 020 del 01 dicembre 2025 (visto di legittimità n. 26256 del 11.12.2025), variato con Deliberazione del Consiglio dei Delegati n. 2 del 08.04.2026 (visto di legittimità n. 9596 del 21.04.2026);',
    'VISTA la Determinazione del Direttore Vicario dell’Area Affari Generali e Programmazione Finanziaria n. 97 del 09.02.2022 con la quale si assegna nel quadro generale dei procedimenti ascrivibili alle linee di attività del Settore Catasto e Ruoli, le funzioni inerenti al ruolo di Responsabile del Procedimento al Capo Settore geom. Stefano Puddu ai sensi della legge n. 241/1990 e s.m.i.;',
    'VISTE le vigenti “Norme Generali sulla distribuzione dell’acqua ad uso irriguo”, approvate con deliberazione del C.d.D. n. 016 del 02.12.2019, che disciplinano le modalità di esercizio del servizio irriguo, gli obblighi posti a carico degli utenti e le conseguenze derivanti dalla violazione delle relative disposizioni;',
    reportText(m),
    'DATO ATTO che le generalità del soggetto individuato quale responsabile dei fatti rilevati, i dati identificativi della pratica, nonché ogni ulteriore elemento utile all’individuazione dell’infrazione rilevata e/o del danno riscontrato, sono riportati nell’elaborato n. 1, che forma parte integrante e sostanziale della presente determinazione, ancorché non materialmente allegato alla stessa;',
    propostaText(m),
    ...userParagraphs(v(m, 'bozza_determinazione_premesse'), 'DATO ATTO altresì che ')
  ]
  premesse.forEach(text => drawStatement(ctx, doc, fR, fB, text))

  const motivazioni = [
    'RITENUTO di dover prendere atto delle risultanze contenute nel predetto Rapporto tecnico di rilevazione e, conseguentemente, di dover procedere alla contestazione dell’infrazione rilevata e alla richiesta degli importi dovuti, secondo quanto indicato nella Proposta di contestazione sopra richiamata;',
    `RITENUTO altresì di dover autorizzare il Settore Catasto, Ruoli e Servizi Territoriali alla predisposizione degli atti conseguenti, ivi compreso l’atto di accertamento e contestazione dell’infrazione, recante la richiesta di pagamento dell’importo complessivo di € ${amountText(m)} a titolo di sanzione, rimborso spese e/o risarcimento danni, nonché alla relativa notifica al soggetto interessato secondo le modalità previste dalla normativa vigente;`,
    ...userParagraphs(v(m, 'bozza_determinazione_motivazione'), 'RITENUTO altresì che ')
  ]
  motivazioni.forEach(text => drawStatement(ctx, doc, fR, fB, text))

  drawStatement(ctx, doc, fR, fB, 'TUTTO CIÒ premesso e considerato parte integrante e sostanziale del presente atto')
  drawSectionLabel(ctx, doc, fB, 'D E T E R M I N A', 2)

  const rapporto = valueOrBlank(v(m, 'n_rapporto'))
  const dataRapporto = valueOrBlank(v(m, 'data_rapporto_tecnico'))
  const area = valueOrBlank(v(m, 'area'), '__________')
  const settore = valueOrBlank(v(m, 'settore'), '__________')
  const artRef = valueOrBlank(v(m, 'articoli_violati_riferimento'), 'dell’art. ____')
  const protocollo = valueOrBlank(v(m, 'protocollo_fascicolo_numero'))
  const dataProtocollo = valueOrBlank(v(m, 'protocollo_fascicolo_data'))
  const importo = amountText(m)

  const punti: Array<[string, string]> = [
    ['di prendere atto', `del Rapporto tecnico di rilevazione n. ${rapporto} del ${dataRapporto}, redatto dall’Area ${area} / Settore ${settore}, con il quale sono stati rilevati i fatti riconducibili alla violazione ${artRef} delle “Norme generali sulla distribuzione dell’acqua ad uso irriguo”, approvate con Deliberazione del C.d.D. n. 016 del 02.12.2019`],
    ['di dare atto', 'che le generalità del soggetto individuato quale responsabile dei fatti rilevati, i dati identificativi della pratica, nonché ogni ulteriore elemento utile all’individuazione dell’infrazione rilevata e/o del danno riscontrato, sono riportati nell’elaborato n. 1, che forma parte integrante e sostanziale della presente determinazione, ancorché non materialmente allegato alla stessa'],
    ['di approvare', `la Proposta di contestazione prot. n. ${protocollo} del ${dataProtocollo}, predisposta dal Settore Catasto, Ruoli e Servizi Territoriali, finalizzata alla contestazione dell’infrazione rilevata e alla quantificazione degli importi dovuti`],
    ['di disporre', 'che si proceda alla contestazione dell’infrazione alle “Norme generali sulla distribuzione dell’acqua ad uso irriguo” nei confronti del soggetto interessato'],
    ['di autorizzare', `il Settore Catasto, Ruoli e Servizi Territoriali alla predisposizione e notifica del relativo atto di accertamento e contestazione dell’infrazione, recante la richiesta di pagamento dell’importo complessivo di € ${importo}, come quantificato nella Proposta di contestazione sopra richiamata, a titolo di sanzione, rimborso spese e/o risarcimento danni, secondo le modalità previste dalla normativa vigente`],
    ['di dare atto', 'che la presente determinazione sarà trasmessa al Settore Catasto, Ruoli e Servizi Territoriali per gli adempimenti di competenza']
  ]
  punti.forEach(([label, text]) => drawDeterminaPoint(ctx, doc, fR, fB, label, text))

  userParagraphs(v(m, 'bozza_determinazione_dispositivo'), 'di ').forEach(text => {
    const clean = stripTrailingPunctuation(text)
    const mLabel = clean.match(/^(di\s+\S+(?:\s+\S+)?)(?:\s+)(.*)$/i)
    if (mLabel) drawDeterminaPoint(ctx, doc, fR, fB, mLabel[1], mLabel[2])
    else drawParagraph(ctx, doc, fR, ensurePeriod(clean))
  })

  needPage(ctx, doc, 76)
  ctx.y -= 16
  drawCentered(ctx.page, 'IL DIRETTORE DELL’AREA AFFARI GENERALI E', fB, 11, ctx.y)
  ctx.y -= 14
  drawCentered(ctx.page, 'PROGRAMMAZIONE FINANZIARIA', fB, 11, ctx.y)
  ctx.y -= 17
  drawCentered(ctx.page, 'Dott.ssa Patrizia Mattioni', fR, 11, ctx.y)

  return await doc.save()
}
